const decode=(k:string):{suit:Suit;value:Value}=>{const suits:Record<string,Suit>={s:'spade',h:'heart',d:'diamond',c:'club'};return {suit:suits[k.slice(-1)],value:k.slice(0,-1).toLowerCase() as Value}}
