const TIER_D_GUIDANCE_BY_LEVEL: Record<number, string> = {
  1: 'LEVEL 1 — Build G1 first. Put three cards from your hand into P1, then combine them with the two shared cards in the center marked G1. G1 must become your weakest legal five-card hand. Tap one card, then tap another card to swap their positions.',
  2: 'LEVEL 2 — Build G2 next. P2 also receives three private cards and combines with the two shared G2 cards. G2 must be stronger than G1. Read the shown AI hands first, then decide how much strength you need to spend here.',
  3: 'LEVEL 3 — Save the best of your hand for G3. Place five cards in P3; together with the G3 shared cards they make your final and strongest hand. A legal order always rises from G1, to G2, to G3.',
  4: 'LEVEL 4 — Your goal is not simply one huge hand. You must distribute all eleven cards across three piles without making G1 stronger than G2 or G2 stronger than G3. A foul breaks the hand order, so check all three piles before Reveal.',
  5: 'LEVEL 5 — The AI cards are still face up in Bronze. Compare every shown AI pile with yours before committing. Put only enough strength into a pile you expect to win, and protect the cards needed for the later piles.',
  6: 'LEVEL 6 — Practice swapping. Select a card in any pile, then select a second card to exchange them. Keep adjusting until your weakest pile is safely weak, your middle pile is stronger, and your final pile is your best chance to score.',
  7: 'LEVEL 7 — Shared cards belong to their matching game only: G1 cards help P1, G2 cards help P2, and G3 cards help P3. Always evaluate a pile together with its two center cards, not from your private cards alone.',
  8: 'LEVEL 8 — Each Match has three games. Win G1 for 4 points, G2 for 6 points, and G3 for 8 points. A tied pile favors you, so a solid equal hand can be enough when saving stronger cards for another pile.',
  9: 'LEVEL 9 — Winning all three games is a Triple Sweep and adds a 5-point bonus. Do not chase a sweep blindly: a balanced 2–1 result can still beat the highest-scoring AI and is often the safer way to clear a Match.',
  10: 'LEVEL 10 — Before Reveal, review the complete plan: P1 is weakest, P2 is stronger, P3 is strongest; each pile uses its own two shared cards. Read the exposed AI hands, arrange calmly, then Reveal when the three-pile order is legal.',
  11: 'LEVEL 11 — A Level contains three Matches. Your total score is compared with the highest AI score across the Level, so recover after one difficult Match instead of gambling every card in the first one. Bronze continues to show the AI hands while you practice.',
  12: 'LEVEL 12 — Learn to budget strength. G1 is worth 4 points, G2 is worth 6, and G3 is worth 8, so G3 matters most—but it cannot be built first if that leaves G1 or G2 illegally strong. Build a legal foundation before chasing points.',
  13: 'LEVEL 13 — Look for the AI’s weak pile. If an opponent has invested too little in G1 or G2, win that pile efficiently and reserve premium cards for G3. TriplePoker rewards the best distribution of cards, not just the best single hand.',
  14: 'LEVEL 14 — Starting at Silver League, Missions appear beside the three games. A Mission can award bonus points even when you do not win that pile. Plan a hand that can compete with the AI while also meeting the Mission requirement when possible.',
  15: 'LEVEL 15 — Completing every Mission in a Match creates a Combo; completing all three creates a Super Combo. These bonuses are valuable, but a Mission hand must still respect the G1 → G2 → G3 order. Never turn a legal Match into a foul for a bonus.',
  16: 'LEVEL 16 — Items give you controlled second chances. Shuffle deals a fresh hand and refreshes the Match timer; Swap replaces one selected card; Double Pile boosts a chosen pile; Freeze pauses time; Undo is available only in its eligible recovery moment. Each item except Auto Sort can be used once per Match. Use them deliberately.',
  17: 'LEVEL 17 — Bronze is the learning league. At Level 51, Silver starts the timed challenge, Missions, and hidden AI information. The goal of these first twenty levels is to make the hand order and shared-card reading feel automatic before that pressure arrives.',
  18: 'LEVEL 18 — Solo is your route to competitive tables. Clear Level 250 to unlock Tier C, then keep climbing to unlock higher Tiers. Multiplayer tables introduce stronger rivals and advanced table systems after you have learned the three-pile foundation here.',
  19: 'LEVEL 19 — Your journey continues beyond Solo. Tier competition, long-term progress, and your performance as a player lead toward The Arena. Choose the path that suits you, but keep strengthening the same core skill: making three legal, well-balanced hands.',
  20: 'LEVEL 20 — The long road leads toward selection for The Arena and, ultimately, The Last Boss. Solo climbers and multiplayer competitors can both build toward that future. From here, the guidance panel steps back—trust your reads, learn from every reveal, and keep climbing.',
}

function TierDGuidanceCredits({level,visible}:{level:number;visible:boolean}){
 const language=useLanguage(value=>value.language);const motion=useRef(new Animated.Value(0)).current;const [trackHeight,setTrackHeight]=useState(0);const [textHeight,setTextHeight]=useState(0);const source=TIER_D_GUIDANCE_BY_LEVEL[level]??TIER_D_GUIDANCE_BY_LEVEL[20];const message=translate(source,language)
 useEffect(()=>{motion.stopAnimation();motion.setValue(0);if(!visible||level>20||trackHeight<=0||textHeight<=0)return;const distance=trackHeight+textHeight;const loop=Animated.loop(Animated.timing(motion,{toValue:1,duration:Math.max(12000,distance*55),useNativeDriver:true}));loop.start();return()=>loop.stop()},[level,language,message,motion,textHeight,trackHeight,visible])
 if(!visible||level>20)return null
 const translateY=motion.interpolate({inputRange:[0,1],outputRange:[trackHeight,-textHeight]})
 return <View accessibilityRole="text" accessibilityLabel={message} style={[s.tutorialMarquee,{top:'34%',height:102,justifyContent:undefined}]} onLayout={event=>setTrackHeight(event.nativeEvent.layout.height)}><Animated.Text onLayout={event=>setTextHeight(event.nativeEvent.layout.height)} style={[s.tutorialMarqueeText,{left:12,right:12,fontSize:14,lineHeight:21,textAlign:'center',transform:[{translateY}]}]}>{message}</Animated.Text></View>
}

